import React from 'react';
import { Button, InlineLabel, PaginationBar, SearchInput, Select, Stack } from '@oods/components-react';
import '@oods/component-styles/css';

export interface PageProps {
  /** Array of currently applied filter values:
  - field: string (matches a filter descriptor field)
  - operator: "eq" | "in" | "range" | "gt" | "lt" | "between"
  - value: unknown (the selected filter value or values)
 */
  activeFilters?: Record<string, unknown>[];
  /** One fixed category with id and label derived from disposition; no inferred taxonomy. */
  categories: unknown[];
  /** Claim. */
  claim: string;
  /** Operational metadata describing mode, storage model, governance rules, and audit timestamps.
 */
  classificationMetadata: unknown;
  /** Created at. */
  createdAt: string;
  /** Display projection of summary; never truncates persisted content. */
  description?: string;
  /** Disposition. */
  disposition: 'supporting' | 'contradicting' | 'rejected' | 'background';
  /** Computed count of currently active filters. */
  filterCount: number;
  /** Array of available filter descriptors. Each entry defines a filterable dimension:
  - field: string (the schema field to filter on)
  - label: string (display label)
  - type: "select" | "multi-select" | "range" | "boolean" | "date-range"
  - options: array of { value, label } for select/multi-select types
 */
  filters?: Record<string, unknown>[];
  /** Id. */
  id: string;
  /** Display projection of claim; retain the complete source field. */
  label: string;
  /** Only from an explicit event or timestamp projection; absence is unknown, not a fabricated audit event. */
  lastEvent?: string;
  /** Timestamp for the lifecycle event captured in last_event. */
  lastEventAt?: string;
  /** Mission id. */
  missionId?: string;
  /** Origin. */
  origin: 'mcp-agent' | 'deepsearch-worker';
  /** Authoritative nullable server owner_id. Present in this response. */
  ownerId?: string;
  /** user only when an authoritative owner_id is present. */
  ownerType?: 'user';
  /** Optional role name describing how the owner governs the entity. */
  ownershipRole?: string;
  /** Timestamp recording when ownership was last transferred. */
  ownershipTransferredAt?: string;
  /** Current page number (1-based). */
  page: number;
  /** Number of items displayed per page. */
  pageSize: number;
  /** Hint copy surfaced in form fields when the label is empty. */
  placeholder?: string;
  /** Exact disposition; classification dimension, never a lifecycle state. */
  primaryCategoryId: 'supporting' | 'contradicting' | 'rejected' | 'background';
  /** Human-readable breadcrumb path (Electronics > Mobile > Android). */
  primaryCategoryPath?: string;
  /** Project id. */
  projectId: string;
  /** Query. */
  query?: string;
  /** Whether the search input is currently focused or has a non-empty query. */
  searchActive?: boolean;
  /** The current search query string entered by the user. */
  searchQuery?: string;
  /** Session key. */
  sessionKey: string;
  /** Snippet. */
  snippet?: string;
  /** Source id. */
  sourceId: string;
  /** Source sighting count. */
  sourceSightingCount: number;
  /** Source url. */
  sourceUrl: string;
  /** Summary. */
  summary?: string;
  /** Number of canonical tags assigned to the object. */
  tagCount?: number;
  /** Denormalized comma-delimited preview for list renders. */
  tagPreview?: string;
  /** Tags. */
  tags: string[];
  /** Total number of items across all pages. Used to compute total page count. */
  totalItems?: number;
  /** Computed total number of pages (ceil(totalItems / pageSize)). */
  totalPages?: number;
  /** Updated at. */
  updatedAt: string;
  /** Workspace id. */
  workspaceId?: string;
}

type ButtonProps = React.ComponentPropsWithoutRef<typeof Button>;
type InlineLabelProps = React.ComponentPropsWithoutRef<typeof InlineLabel>;
type PaginationBarProps = React.ComponentPropsWithoutRef<typeof PaginationBar>;
type SearchInputProps = React.ComponentPropsWithoutRef<typeof SearchInput>;
type SelectProps = React.ComponentPropsWithoutRef<typeof Select>;
type StackProps = React.ComponentPropsWithoutRef<typeof Stack>;

export const GeneratedUI: React.FC<PageProps> = ({ activeFilters, categories, claim, classificationMetadata, createdAt, description, disposition, filterCount, filters, id, label, lastEvent, lastEventAt, missionId, origin, ownerId, ownerType, ownershipRole, ownershipTransferredAt, page, pageSize, placeholder, primaryCategoryId, primaryCategoryPath, projectId, query, searchActive, searchQuery, sessionKey, snippet, sourceId, sourceSightingCount, sourceUrl, summary, tagCount, tagPreview, tags, totalItems, totalPages, updatedAt, workspaceId }) => {
  const [handleUpdate_session_keyState, setHandleUpdate_session_keyState] = React.useState<string>(String(sessionKey ?? ''));
  /* @oods-local-binding handleUpdate_session_key */ const handleUpdate_session_key = (value: string) => { setHandleUpdate_session_keyState(value); };

  return (
    <main data-oods-shell="screen-list-9">
      <h1 data-oods-shell-heading="true">Evidence</h1>
      <Stack id="screen-list-9" data-oods-component="Stack" data-layout="stack" style={{ display: 'flex', flexDirection: 'column', gap: 'var(--ref-space-cluster-default)' }}>
            <Stack id="list-toolbar-4" data-oods-component="Stack" data-layout="inline" style={{ display: 'flex', flexDirection: 'row', justifyContent: 'space-between', padding: 'var(--ref-space-inset-default)' }}>
                    <SearchInput id="slot-search-1" data-oods-component="SearchInput" label="Session key" placeholder="Enter session key" value={handleUpdate_session_keyState} onUpdate={handleUpdate_session_key} />
                    <Select id="slot-filters-2" data-oods-component="Select" label="Claim" placeholder="Enter claim" required value={claim} />
                    <Button id="slot-toolbar-actions-3" data-oods-component="Button" />
                  </Stack>
            <Stack id="list-items-5" data-oods-component="Stack" data-layout="stack" style={{ display: 'flex', flexDirection: 'column', gap: 'var(--ref-space-cluster-tight)' }}>
                    <InlineLabel id="slot-items-6" data-oods-component="InlineLabel" maxLength={40} label={label} />
                  </Stack>
            <Stack id="list-pagination-7" data-oods-component="Stack" data-layout="inline" style={{ display: 'flex', flexDirection: 'row', justifyContent: 'center', padding: 'var(--ref-space-inset-default)' }}>
                    <PaginationBar id="slot-pagination-8" data-oods-component="PaginationBar" />
                  </Stack>
          </Stack>
    </main>
  );
};

